import { Swiper, SwiperSlide } from "swiper/react";
import { Autoplay } from "swiper/modules";
import "swiper/css";
import { useRef, useState } from "react";

import img1 from "../../assets/17 New star.png";
import img2 from "../../assets/40 create party.png";
import img3 from "../../assets/46 click lock.png";
import img4 from "../../assets/14 gifting classic.png";
import img5 from "../../assets/11 live screen 1.png";
import img6 from "../../assets/10 Get started.png";
import img7 from "../../assets/34 Party event.png";
import img8 from "../../assets/81 expplore     all.png";
import img9 from "../../assets/live stream 2.png";
import img10 from "../../assets/stream feed 1.png";

const sliderData = [
  { img: img1, text: "Live Streaming Fun" },
  { img: img2, text: "Connect with Friends" },
  { img: img3, text: "Earn While You Stream" },
  { img: img4, text: "Join Interactive Games" },
  { img: img5, text: "Be Part of the Community" },
  { img: img6, text: "Win Exciting Rewards" },
  { img: img7, text: "Stream Anytime, Anywhere" },
  { img: img8, text: "Discover New Talents" },
  { img: img9, text: "Host Live Shows" },
  { img: img10, text: "Share Your Moments" },
];

export default function Front() {
  const swiperRef = useRef(null);
  const [activeIndex, setActiveIndex] = useState(0);

  return (
    <section className="bg-black slid">
      {/* Main Slider */}
      <Swiper
        modules={[Autoplay]}
        spaceBetween={20}
        slidesPerView={3}
        centeredSlides={true}
        loop={true}
        onSwiper={(swiper) => (swiperRef.current = swiper)}
        onSlideChange={(swiper) => setActiveIndex(swiper.realIndex)}
        autoplay={{ delay: 3000, disableOnInteraction: false }}
        className="slider-container"
      >
        {sliderData.map((slide, index) => (
          <SwiperSlide key={index} className="slide-item">
            <img src={slide.img} alt={slide.text} className="main-slide-image" />
          </SwiperSlide>
        ))}
      </Swiper>

      {/* Thumbnails */}
      <div className="thumbnail-container">
        {sliderData.map((slide, index) => (
          <div
            key={index}
            className={`thumbnail ${activeIndex === index ? "active" : ""}`}
            onClick={() => swiperRef.current.slideToLoop(index)}
          >
            <img src={slide.img} alt={slide.text} />
          </div>
        ))}
      </div>

      <style>{`

      `}</style>
    </section>
  );
}
